//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
)

func TestEnum_MAV_DISTANCE_SENSOR(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.MAV_DISTANCE_SENSOR
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.MAV_DISTANCE_SENSOR_LASER.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.MAV_DISTANCE_SENSOR
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.MAV_DISTANCE_SENSOR_LASER, dec)
	})
}
